import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  isLoading, 
  className = '', 
  disabled,
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center rounded-lg font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none";

  const variants = {
    primary: "bg-indigo-600 text-white hover:bg-indigo-700 focus:ring-indigo-500 shadow-sm",
    secondary: "bg-slate-800 text-white hover:bg-slate-900 focus:ring-slate-500 shadow-sm",
    outline: "border border-slate-300 bg-white text-slate-700 hover:bg-slate-50 focus:ring-indigo-500",
    ghost: "text-slate-600 hover:bg-slate-100 hover:text-slate-900",
  };

  const sizes = {
    sm: "h-8 px-3 text-sm",
    md: "h-10 px-4 py-2",
    lg: "h-12 px-6 text-lg",
  };

  return (
    <button
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      disabled={disabled || isLoading}
      {...props}
    >
      {isLoading ? (
        <>
          <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
          처리 중...
        </>
      ) : (
        children
      )}
    </button>
  );
};

import { ProcessedSlice } from '../types';

/**
 * Calculates the "energy" or "noise" of a row of pixels.
 * Lower energy means the row is more uniform (e.g., solid background), making it a good place to cut.
 */
const calculateRowEnergy = (
  data: Uint8ClampedArray,
  width: number,
  y: number,
  sampleRate: number = 5
): number => {
  const rowStart = y * width * 4;
  let energy = 0;
  let previousPixel = { r: data[rowStart], g: data[rowStart + 1], b: data[rowStart + 2] };

  // Heuristic 1: Variance across the row (is it a solid color line?)
  // We check every Nth pixel to save performance
  for (let x = sampleRate; x < width; x += sampleRate) {
    const i = rowStart + x * 4;
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];

    const diff = Math.abs(r - previousPixel.r) + Math.abs(g - previousPixel.g) + Math.abs(b - previousPixel.b);
    energy += diff;
    previousPixel = { r, g, b };
  }

  // Heuristic 2: Check standard deviation from pure white or pure black (common backgrounds)
  // This penalizes cutting through colorful images vs white space
  const midIndex = rowStart + Math.floor(width / 2) * 4;
  const isWhite = data[midIndex] > 240 && data[midIndex + 1] > 240 && data[midIndex + 2] > 240;

  if (isWhite) {
    energy = energy * 0.5; // Favor white backgrounds
  }

  return energy;
};

/**
 * Finds the optimal cut point within a search window around the target Y.
 */
const findOptimalCutPoint = (
  ctx: CanvasRenderingContext2D,
  width: number,
  targetY: number,
  totalHeight: number,
  searchWindow: number = 1500 // Search up/down by this amount
): number => {
  // Don't search beyond image bounds
  if (targetY >= totalHeight) return totalHeight;

  const startSearchY = Math.max(0, targetY - searchWindow);
  const endSearchY = Math.min(totalHeight, targetY + (searchWindow / 2)); // Look ahead less than looking back
  const heightToSearch = endSearchY - startSearchY;

  if (heightToSearch <= 0) return targetY;

  try {
    const imageData = ctx.getImageData(0, startSearchY, width, heightToSearch);
    const data = imageData.data;

    let minEnergy = Infinity;
    let bestLocalY = targetY - startSearchY; // Default to original target if fails

    // Scan rows
    for (let y = 0; y < heightToSearch; y++) {
      // Skip very top/bottom edges of search area to avoid tiny slices if possible
      const energy = calculateRowEnergy(data, width, y);

      // We want the closest efficient cut to the target height, so we penalize distance slightly
      // This prevents the cutter from always jumping to the top of the search window
      const distFromTarget = Math.abs((startSearchY + y) - targetY);
      const distancePenalty = distFromTarget * 10; // Weight factor

      const totalScore = energy + distancePenalty;

      if (totalScore < minEnergy) {
        minEnergy = totalScore;
        bestLocalY = y;
      }
    }

    return startSearchY + bestLocalY;

  } catch (e) {
    console.error("Error analyzing pixels", e);
    return targetY;
  }
};

export const processImage = async (
  imageFile: File,
  targetHeight: number,
  onProgress: (progress: number) => void
): Promise<ProcessedSlice[]> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(imageFile);

    img.onload = async () => {
      try {
        const canvas = document.createElement('canvas');
        const width = img.width;
        const height = img.height;
        canvas.width = width;
        canvas.height = height;

        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        if (!ctx) throw new Error('Could not get canvas context');

        ctx.drawImage(img, 0, 0);

        const slices: ProcessedSlice[] = [];
        let currentY = 0;
        let sliceIndex = 0;

        while (currentY < height) {
          // Update progress
          onProgress(Math.min(100, Math.round((currentY / height) * 100)));

          // Calculate where we WANT to cut
          let nextCutY = currentY + targetHeight;

          // If this is the last chunk (rest of image is smaller than target), just take it all
          if (nextCutY >= height) {
            nextCutY = height;
          } else {
            // SMART ANALYSIS: Find best cut point around the target
            // We give it a buffer of +/- 1500px to find whitespace
            nextCutY = findOptimalCutPoint(ctx, width, nextCutY, height, 1500);
          }

          const sliceHeight = nextCutY - currentY;

          if (sliceHeight <= 0) break; // Safety break

          // Create a temporary canvas for this slice
          const sliceCanvas = document.createElement('canvas');
          sliceCanvas.width = width;
          sliceCanvas.height = sliceHeight;
          const sliceCtx = sliceCanvas.getContext('2d');

          if (sliceCtx) {
            // Draw the portion
            sliceCtx.drawImage(
              canvas,
              0, currentY, width, sliceHeight, // Source
              0, 0, width, sliceHeight        // Dest
            );

            // Convert to blob
            const blob = await new Promise<Blob>((res, rej) => 
              sliceCanvas.toBlob(b => b ? res(b) : rej(new Error('Blob failed')), 'image/jpeg', 0.95)
            );

            slices.push({
              id: `slice-${sliceIndex}`,
              blob,
              url: URL.createObjectURL(blob),
              width,
              height: sliceHeight,
              index: sliceIndex + 1
            });
          }

          currentY = nextCutY;
          sliceIndex++;

          // Yield to main thread to update UI
          await new Promise(r => requestAnimationFrame(r));
        }

        onProgress(100);
        URL.revokeObjectURL(url);
        resolve(slices);

      } catch (error) {
        URL.revokeObjectURL(url);
        reject(error);
      }
    };

    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error("Failed to load image"));
    };

    img.src = url;
  });
};

import React, { useCallback, useState } from 'react';
import { UploadCloud, Image as ImageIcon } from 'lucide-react';

interface DropzoneProps {
  onFileSelect: (file: File) => void;
}

export const Dropzone: React.FC<DropzoneProps> = ({ onFileSelect }) => {
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const file = e.dataTransfer.files[0];
      if (file.type.startsWith('image/')) {
        onFileSelect(file);
      }
    }
  }, [onFileSelect]);

  const handleInputChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      onFileSelect(e.target.files[0]);
    }
  }, [onFileSelect]);

  return (
    <div
      className={`relative border-2 border-dashed rounded-xl p-12 transition-all duration-200 ease-in-out text-center cursor-pointer group
        ${isDragging 
          ? 'border-indigo-500 bg-indigo-50/50' 
          : 'border-slate-300 hover:border-indigo-400 hover:bg-slate-50'
        }`}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      onClick={() => document.getElementById('file-upload')?.click()}
    >
      <input
        id="file-upload"
        type="file"
        className="hidden"
        accept="image/png, image/jpeg, image/jpg, image/webp"
        onChange={handleInputChange}
      />

      <div className="flex flex-col items-center justify-center space-y-4">
        <div className={`p-4 rounded-full transition-colors ${isDragging ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-500 group-hover:bg-indigo-50 group-hover:text-indigo-500'}`}>
          <UploadCloud size={32} />
        </div>
        <div className="space-y-1">
          <p className="text-lg font-semibold text-slate-700">
            이미지를 드래그하거나 클릭하여 업로드
          </p>
          <p className="text-sm text-slate-500">
            JPG, PNG, WEBP (최대 해상도 제한 없음)
          </p>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { ProcessedSlice } from '../types';
import { Download, Archive, RefreshCw } from 'lucide-react';
import { Button } from './Button';
import JSZip from 'jszip';
import { saveAs } from 'file-saver';

interface ResultPreviewProps {
  slices: ProcessedSlice[];
  onReset: () => void;
  originalFileName: string;
}

export const ResultPreview: React.FC<ResultPreviewProps> = ({ slices, onReset, originalFileName }) => {
  const handleDownloadAll = async () => {
    const zip = new JSZip();
    const baseName = originalFileName.replace(/\.[^/.]+$/, "");

    slices.forEach((slice) => {
      // zero pad the index for proper sorting: 01, 02, etc.
      const padIndex = String(slice.index).padStart(2, '0');
      zip.file(`${baseName}_${padIndex}.jpg`, slice.blob);
    });

    const content = await zip.generateAsync({ type: "blob" });
    saveAs(content, `${baseName}_slices.zip`);
  };

  const handleDownloadSingle = (slice: ProcessedSlice) => {
    const baseName = originalFileName.replace(/\.[^/.]+$/, "");
    const padIndex = String(slice.index).padStart(2, '0');
    saveAs(slice.blob, `${baseName}_${padIndex}.jpg`);
  };

  return (
    <div className="animate-fade-in space-y-8">
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 flex flex-col md:flex-row items-center justify-between gap-4 sticky top-4 z-10">
        <div>
          <h2 className="text-xl font-bold text-slate-800">작업 완료!</h2>
          <p className="text-slate-500">총 {slices.length}개의 이미지로 분할되었습니다.</p>
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
           <Button variant="outline" onClick={onReset} className="flex-1 md:flex-none">
            <RefreshCw size={16} className="mr-2" />
            다시하기
          </Button>
          <Button onClick={handleDownloadAll} className="flex-1 md:flex-none">
            <Archive size={16} className="mr-2" />
            전체 다운로드 (ZIP)
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {slices.map((slice) => (
          <div key={slice.id} className="group relative bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow">
            <div className="aspect-[3/4] bg-slate-100 relative overflow-hidden flex items-center justify-center">
                {/* Image preview with object-contain to show full slice */}
              <img 
                src={slice.url} 
                alt={`Slice ${slice.index}`} 
                className="w-full h-full object-contain bg-slate-50"
              />
              <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100">
                  <Button size="sm" variant="secondary" onClick={() => handleDownloadSingle(slice)}>
                      <Download size={16} className="mr-2" />
                      개별 다운로드
                  </Button>
              </div>
            </div>
            <div className="p-4 border-t border-slate-100 flex justify-between items-center">
              <div>
                <span className="text-xs font-semibold text-indigo-600 bg-indigo-50 px-2 py-1 rounded-full">
                  #{String(slice.index).padStart(2, '0')}
                </span>
              </div>
              <div className="text-xs text-slate-500 font-mono">
                {slice.width} x {slice.height}px
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Dropzone } from './components/Dropzone';
import { ResultPreview } from './components/ResultPreview';
import { processImage } from './utils/imageProcessor';
import { ProcessedSlice } from './types';
import { Scissors, Settings, Zap } from 'lucide-react';
import { Button } from './components/Button';

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [slices, setSlices] = useState<ProcessedSlice[]>([]);
  const [targetHeight, setTargetHeight] = useState(10000);

  const handleFileSelect = async (selectedFile: File) => {
    setFile(selectedFile);
    setIsProcessing(true);
    setProgress(0);
    setSlices([]);

    try {
      // Small delay to let UI render the loading state
      setTimeout(async () => {
        const result = await processImage(selectedFile, targetHeight, (p) => setProgress(p));
        setSlices(result);
        setIsProcessing(false);
      }, 100);
    } catch (error) {
      console.error("Processing failed", error);
      alert("이미지 처리 중 오류가 발생했습니다.");
      setIsProcessing(false);
      setFile(null);
    }
  };

  const handleReset = () => {
    setFile(null);
    setSlices([]);
    setProgress(0);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-20">
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-600 p-2 rounded-lg text-white">
              <Scissors size={20} />
            </div>
            <h1 className="text-xl font-bold text-slate-900 tracking-tight">상세페이지 재단사</h1>
          </div>
          <div className="hidden sm:flex items-center gap-4 text-sm text-slate-500">
             <span className="flex items-center gap-1">
                 <Zap size={14} className="text-yellow-500" fill="currentColor"/>
                 스마트 분석 엔진 탑재
             </span>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-6xl w-full mx-auto px-4 py-12">
        {!file ? (
          <div className="max-w-2xl mx-auto space-y-8 animate-fade-in-up">
            <div className="text-center space-y-4">
              <h2 className="text-3xl font-extrabold text-slate-900">
                긴 상세페이지, 한 번에 자르세요
              </h2>
              <p className="text-lg text-slate-600 max-w-lg mx-auto leading-relaxed">
                이미지 내용을 스마트하게 분석하여 글자나 상품이 잘리지 않도록 
                <span className="text-indigo-600 font-semibold"> 최적의 위치</span>를 찾아 자동으로 분할합니다.
              </p>
            </div>

            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 space-y-6">
               <div className="flex items-center justify-between border-b border-slate-100 pb-4">
                   <div className="flex items-center gap-2 text-slate-700 font-medium">
                       <Settings size={18} />
                       <span>분할 설정</span>
                   </div>
               </div>

               <div className="space-y-3">
                   <label className="block text-sm font-medium text-slate-700">
                       목표 높이 (픽셀)
                   </label>
                   <div className="flex items-center gap-4">
                       <input 
                            type="range" 
                            min="1000" 
                            max="20000" 
                            step="1000"
                            value={targetHeight}
                            onChange={(e) => setTargetHeight(Number(e.target.value))}
                            className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                       />
                       <span className="text-indigo-600 font-mono font-bold w-20 text-right">
                           {targetHeight.toLocaleString()}px
                       </span>
                   </div>
                   <p className="text-xs text-slate-400">
                       * 설정한 높이 근처의 여백을 찾아 자동으로 조정됩니다. (기본값: 10,000px)
                   </p>
               </div>
            </div>

            <Dropzone onFileSelect={handleFileSelect} />

          </div>
        ) : isProcessing ? (
          <div className="max-w-xl mx-auto text-center space-y-8 py-20 animate-pulse">
             <div className="relative w-24 h-24 mx-auto">
                 <div className="absolute inset-0 border-4 border-slate-200 rounded-full"></div>
                 <div 
                    className="absolute inset-0 border-4 border-indigo-600 rounded-full border-t-transparent animate-spin"
                 ></div>
             </div>
             <div className="space-y-2">
                 <h3 className="text-xl font-bold text-slate-900">이미지 분석 및 분할 중...</h3>
                 <p className="text-slate-500">이미지 크기에 따라 시간이 소요될 수 있습니다.</p>
             </div>
             <div className="w-full bg-slate-200 rounded-full h-2.5 dark:bg-slate-700">
                <div className="bg-indigo-600 h-2.5 rounded-full transition-all duration-300" style={{ width: `${progress}%` }}></div>
             </div>
             <p className="font-mono text-slate-400">{progress}% 완료</p>
          </div>
        ) : (
          <ResultPreview 
            slices={slices} 
            onReset={handleReset} 
            originalFileName={file.name}
          />
        )}
      </main>

      <footer className="bg-white border-t border-slate-200 py-8 mt-12">
          <div className="max-w-6xl mx-auto px-4 text-center text-slate-400 text-sm">
              &copy; {new Date().getFullYear()} 상세페이지 재단사. Local processing ensures privacy.
          </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { ProcessedSlice } from '../types';
import { Download, Archive, RefreshCw } from 'lucide-react';
import { Button } from './Button';
import JSZip from 'jszip';
import saveAs from 'file-saver';

interface ResultPreviewProps {
  slices: ProcessedSlice[];
  onReset: () => void;
  originalFileName: string;
}

export const ResultPreview: React.FC<ResultPreviewProps> = ({ slices, onReset, originalFileName }) => {
  const handleDownloadAll = async () => {
    const zip = new JSZip();
    const baseName = originalFileName.replace(/\.[^/.]+$/, "");

    slices.forEach((slice) => {
      // zero pad the index for proper sorting: 01, 02, etc.
      const padIndex = String(slice.index).padStart(2, '0');
      zip.file(`${baseName}_${padIndex}.jpg`, slice.blob);
    });

    const content = await zip.generateAsync({ type: "blob" });
    saveAs(content, `${baseName}_slices.zip`);
  };

  const handleDownloadSingle = (slice: ProcessedSlice) => {
    const baseName = originalFileName.replace(/\.[^/.]+$/, "");
    const padIndex = String(slice.index).padStart(2, '0');
    saveAs(slice.blob, `${baseName}_${padIndex}.jpg`);
  };

  return (
    <div className="animate-fade-in space-y-8">
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 flex flex-col md:flex-row items-center justify-between gap-4 sticky top-4 z-10">
        <div>
          <h2 className="text-xl font-bold text-slate-800">작업 완료!</h2>
          <p className="text-slate-500">총 {slices.length}개의 이미지로 분할되었습니다.</p>
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
           <Button variant="outline" onClick={onReset} className="flex-1 md:flex-none">
            <RefreshCw size={16} className="mr-2" />
            다시하기
          </Button>
          <Button onClick={handleDownloadAll} className="flex-1 md:flex-none">
            <Archive size={16} className="mr-2" />
            전체 다운로드 (ZIP)
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {slices.map((slice) => (
          <div key={slice.id} className="group relative bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow">
            <div className="aspect-[3/4] bg-slate-100 relative overflow-hidden flex items-center justify-center">
