            JPG, PNG, WEBP (여러 장 선택 가능)
          </p>
        </div>
      </div>
    </div>
  );
};

import { ProcessedSlice, ProcessingMode } from '../types';

/**
 * Calculates the "energy" or "noise" of a row of pixels.
 */
const calculateRowEnergy = (
  data: Uint8ClampedArray,
  width: number,
  y: number,
  sampleRate: number = 5
): number => {
  const rowStart = y * width * 4;
  let energy = 0;
  let previousPixel = { r: data[rowStart], g: data[rowStart + 1], b: data[rowStart + 2] };

  // Heuristic 1: Variance across the row
  for (let x = sampleRate; x < width; x += sampleRate) {
    const i = rowStart + x * 4;
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];

    const diff = Math.abs(r - previousPixel.r) + Math.abs(g - previousPixel.g) + Math.abs(b - previousPixel.b);
    energy += diff;
    previousPixel = { r, g, b };
  }

  // Heuristic 2: Check standard deviation from pure white
  const midIndex = rowStart + Math.floor(width / 2) * 4;
  const isWhite = data[midIndex] > 240 && data[midIndex + 1] > 240 && data[midIndex + 2] > 240;

  if (isWhite) {
    energy = energy * 0.5;
  }

  return energy;
};

/**
 * Finds the optimal cut point within a search window around the target Y.
 */
const findOptimalCutPoint = (
  ctx: CanvasRenderingContext2D,
  width: number,
  targetY: number,
  totalHeight: number,
  searchWindow: number = 1500
): number => {
  if (targetY >= totalHeight) return totalHeight;

  const startSearchY = Math.max(0, targetY - searchWindow);
  const endSearchY = Math.min(totalHeight, targetY + (searchWindow / 2));
  const heightToSearch = endSearchY - startSearchY;

  if (heightToSearch <= 0) return targetY;

  try {
    const imageData = ctx.getImageData(0, startSearchY, width, heightToSearch);
    const data = imageData.data;

    let minEnergy = Infinity;
    let bestLocalY = targetY - startSearchY;

    for (let y = 0; y < heightToSearch; y++) {
      const energy = calculateRowEnergy(data, width, y);
      const distFromTarget = Math.abs((startSearchY + y) - targetY);
      const distancePenalty = distFromTarget * 10;
      const totalScore = energy + distancePenalty;

      if (totalScore < minEnergy) {
        minEnergy = totalScore;
        bestLocalY = y;
      }
    }

    return startSearchY + bestLocalY;

  } catch (e) {
    console.error("Error analyzing pixels", e);
    return targetY;
  }
};

const loadImage = (file: File): Promise<HTMLImageElement> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(file);
    img.onload = () => {
      resolve(img);
      // NOTE: We don't revoke URL immediately as we might need src for drawing. 
      // It will be handled by caller or browser GC eventually if we are careful.
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error(`Failed to load image: ${file.name}`));
    };
    img.src = url;
  });
};

/**
 * Processes a single image: Splits it vertically (Slice) or Reshapes it (Stitch single)
 */
const processSingleImage = async (
  img: HTMLImageElement,
  fileName: string,
  targetHeight: number,
  mode: ProcessingMode,
  quality: number,
  baseIndexOffset: number
): Promise<ProcessedSlice[]> => {
  const canvas = document.createElement('canvas');
  const width = img.width;
  const height = img.height;
  canvas.width = width;
  canvas.height = height;

  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  if (!ctx) throw new Error('Could not get canvas context');

  ctx.drawImage(img, 0, 0);

  // Phase 1: Cutting
  const chunks: { canvas: HTMLCanvasElement; width: number; height: number }[] = [];
  let currentY = 0;

  while (currentY < height) {
    let nextCutY = currentY + targetHeight;

    if (nextCutY >= height) {
      nextCutY = height;
    } else {
      nextCutY = findOptimalCutPoint(ctx, width, nextCutY, height, 1500);
    }

    const sliceHeight = nextCutY - currentY;
    if (sliceHeight <= 0) break;

    const sliceCanvas = document.createElement('canvas');
    sliceCanvas.width = width;
    sliceCanvas.height = sliceHeight;
    const sliceCtx = sliceCanvas.getContext('2d');

    if (sliceCtx) {
      sliceCtx.drawImage(canvas, 0, currentY, width, sliceHeight, 0, 0, width, sliceHeight);
      chunks.push({ canvas: sliceCanvas, width: width, height: sliceHeight });
    }

    currentY = nextCutY;
    await new Promise(r => requestAnimationFrame(r)); // Yield
  }

  // Phase 2: Output
  const results: ProcessedSlice[] = [];

  if (mode === 'stitch') {
    // Stitch chunks horizontally
    const totalWidth = width * chunks.length;
    const maxHeight = Math.max(...chunks.map(c => c.height));

    const stitchedCanvas = document.createElement('canvas');
    stitchedCanvas.width = totalWidth;
    stitchedCanvas.height = maxHeight;
    const stitchedCtx = stitchedCanvas.getContext('2d');
    if (!stitchedCtx) throw new Error("Canvas error");

    chunks.forEach((chunk, index) => {
      stitchedCtx.drawImage(chunk.canvas, index * width, 0);
    });

    const blob = await new Promise<Blob>((res, rej) => 
      stitchedCanvas.toBlob(b => b ? res(b) : rej(new Error('Blob failed')), 'image/jpeg', quality)
    );

    results.push({
      id: `stitched-${fileName}`,
      blob,
      url: URL.createObjectURL(blob),
      width: totalWidth,
      height: maxHeight,
      index: baseIndexOffset + 1
    });

  } else {
    // Save individual chunks
    for (let i = 0; i < chunks.length; i++) {
       const chunk = chunks[i];
       const blob = await new Promise<Blob>((res, rej) => 
         chunk.canvas.toBlob(b => b ? res(b) : rej(new Error('Blob failed')), 'image/jpeg', quality)
       );

       results.push({
         id: `slice-${fileName}-${i}`,
         blob,
         url: URL.createObjectURL(blob),
         width: chunk.width,
         height: chunk.height,
         index: baseIndexOffset + i + 1
       });
    }
  }

  return results;
};

/**
 * Main function to process one or multiple images
 */
export const processImages = async (
  files: File[],
  targetHeight: number,
  mode: ProcessingMode,
  quality: number,
  onProgress: (progress: number) => void
): Promise<ProcessedSlice[]> => {

  // CASE 1: Multi-file Stitching (Horizontal join of distinct images)
  if (mode === 'stitch' && files.length > 1) {
    onProgress(10);
    const images = await Promise.all(files.map(loadImage));
    onProgress(40);

    // Calculate dimensions
    const totalWidth = images.reduce((sum, img) => sum + img.width, 0);
    const maxHeight = Math.max(...images.map(img => img.height));

    const canvas = document.createElement('canvas');
    canvas.width = totalWidth;
    canvas.height = maxHeight;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error("Canvas context failed");

    // Draw images side-by-side
    let currentX = 0;
    images.forEach(img => {
      ctx.drawImage(img, currentX, 0);
      currentX += img.width;
    });

    onProgress(80);

    const blob = await new Promise<Blob>((res, rej) => 
      canvas.toBlob(b => b ? res(b) : rej(new Error('Blob failed')), 'image/jpeg', quality)
    );

    onProgress(100);

    // Clean up loaded images source
    images.forEach(img => URL.revokeObjectURL(img.src));

    return [{
      id: 'multi-stitch-result',
      blob,
      url: URL.createObjectURL(blob),
      width: totalWidth,
      height: maxHeight,
      index: 1
    }];
  }

  // CASE 2: Single file Stitch OR Slice (Single or Batch)
  // Process each file independently using the "Cut" logic
  let allResults: ProcessedSlice[] = [];
  let currentIndex = 0;

  for (let i = 0; i < files.length; i++) {
    const progressStart = (i / files.length) * 100;
    const progressEnd = ((i + 1) / files.length) * 100;

    // Pass a local progress callback that maps to global progress
    // Note: We can't easily pass this down perfectly, so we approximate
    onProgress(progressStart);

    const img = await loadImage(files[i]);
    const results = await processSingleImage(
      img, 
      files[i].name, 
      targetHeight, 
      mode, 
      quality, 
      currentIndex
    );

    allResults = [...allResults, ...results];
    currentIndex += results.length;
    URL.revokeObjectURL(img.src);

    onProgress(progressEnd);
  }

  return allResults;
};

