import React, { useCallback, useState } from 'react';
import { UploadCloud, Image as ImageIcon, Files } from 'lucide-react';

interface DropzoneProps {
  onFilesSelect: (files: File[]) => void;
}

export const Dropzone: React.FC<DropzoneProps> = ({ onFilesSelect }) => {
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const files = (Array.from(e.dataTransfer.files) as File[]).filter(file => file.type.startsWith('image/'));
      if (files.length > 0) {
        onFilesSelect(files);
      }
    }
  }, [onFilesSelect]);

  const handleInputChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const files = (Array.from(e.target.files) as File[]).filter(file => file.type.startsWith('image/'));
      if (files.length > 0) {
        onFilesSelect(files);
      }
    }
  }, [onFilesSelect]);

  return (
    <div
      className={`relative border-2 border-dashed rounded-xl p-12 transition-all duration-200 ease-in-out text-center cursor-pointer group
        ${isDragging 
          ? 'border-indigo-500 bg-indigo-50/50' 
          : 'border-slate-300 hover:border-indigo-400 hover:bg-slate-50'
        }`}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      onClick={() => document.getElementById('file-upload')?.click()}
    >
      <input
        id="file-upload"
        type="file"
        className="hidden"
        multiple
        accept="image/png, image/jpeg, image/jpg, image/webp"
        onChange={handleInputChange}
      />

      <div className="flex flex-col items-center justify-center space-y-4">
        <div className={`p-4 rounded-full transition-colors ${isDragging ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-500 group-hover:bg-indigo-50 group-hover:text-indigo-500'}`}>
          {isDragging ? <Files size={32} /> : <UploadCloud size={32} />}
        </div>
        <div className="space-y-1">
          <p className="text-lg font-semibold text-slate-700">
            이미지를 드래그하거나 클릭하여 업로드
          </p>
          <p className="text-sm text-slate-500">
            JPG, PNG, WEBP (여러 장 선택 가능)
          </p>
        </div>
      </div>
    </div>
  );
};

import { ProcessedSlice, ProcessingMode } from '../types';

/**
 * Calculates the "energy" or "noise" of a row of pixels.
 */
const calculateRowEnergy = (
  data: Uint8ClampedArray,
  width: number,
  y: number,
  sampleRate: number = 5
): number => {
  const rowStart = y * width * 4;
  let energy = 0;
  let previousPixel = { r: data[rowStart], g: data[rowStart + 1], b: data[rowStart + 2] };

  // Heuristic 1: Variance across the row
  for (let x = sampleRate; x < width; x += sampleRate) {
    const i = rowStart + x * 4;
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];

    const diff = Math.abs(r - previousPixel.r) + Math.abs(g - previousPixel.g) + Math.abs(b - previousPixel.b);
    energy += diff;
    previousPixel = { r, g, b };
  }

  // Heuristic 2: Check standard deviation from pure white
  const midIndex = rowStart + Math.floor(width / 2) * 4;
  const isWhite = data[midIndex] > 240 && data[midIndex + 1] > 240 && data[midIndex + 2] > 240;

  if (isWhite) {
    energy = energy * 0.5;
  }

  return energy;
};

/**
 * Finds the optimal cut point within a search window around the target Y.
 */
const findOptimalCutPoint = (
  ctx: CanvasRenderingContext2D,
  width: number,
  targetY: number,
  totalHeight: number,
  searchWindow: number = 1500
): number => {
  if (targetY >= totalHeight) return totalHeight;

  const startSearchY = Math.max(0, targetY - searchWindow);
  const endSearchY = Math.min(totalHeight, targetY + (searchWindow / 2));
  const heightToSearch = endSearchY - startSearchY;

  if (heightToSearch <= 0) return targetY;

  try {
    const imageData = ctx.getImageData(0, startSearchY, width, heightToSearch);
    const data = imageData.data;

    let minEnergy = Infinity;
    let bestLocalY = targetY - startSearchY;

    for (let y = 0; y < heightToSearch; y++) {
      const energy = calculateRowEnergy(data, width, y);
      const distFromTarget = Math.abs((startSearchY + y) - targetY);
      const distancePenalty = distFromTarget * 10;
      const totalScore = energy + distancePenalty;

      if (totalScore < minEnergy) {
        minEnergy = totalScore;
        bestLocalY = y;
      }
    }

    return startSearchY + bestLocalY;

  } catch (e) {
    console.error("Error analyzing pixels", e);
    return targetY;
  }
};

const loadImage = (file: File): Promise<HTMLImageElement> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(file);
    img.onload = () => {
      resolve(img);
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error(`Failed to load image: ${file.name}`));
    };
    img.src = url;
  });
};

interface Chunk {
  canvas: HTMLCanvasElement;
  width: number;
  height: number;
}

/**
 * Splits a single image into chunks based on targetHeight using smart cutting.
 */
const generateChunks = async (
  img: HTMLImageElement,
  targetHeight: number
): Promise<Chunk[]> => {
  const canvas = document.createElement('canvas');
  const width = img.width;
  const height = img.height;
  canvas.width = width;
  canvas.height = height;

  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  if (!ctx) throw new Error('Could not get canvas context');

  ctx.drawImage(img, 0, 0);

  const chunks: Chunk[] = [];
  let currentY = 0;

  while (currentY < height) {
    let nextCutY = currentY + targetHeight;

    if (nextCutY >= height) {
      nextCutY = height;
    } else {
      nextCutY = findOptimalCutPoint(ctx, width, nextCutY, height, 1500);
    }

    const sliceHeight = nextCutY - currentY;
    if (sliceHeight <= 0) break;

    const sliceCanvas = document.createElement('canvas');
    sliceCanvas.width = width;
    sliceCanvas.height = sliceHeight;
    const sliceCtx = sliceCanvas.getContext('2d');

    if (sliceCtx) {
      sliceCtx.drawImage(canvas, 0, currentY, width, sliceHeight, 0, 0, width, sliceHeight);
      chunks.push({ canvas: sliceCanvas, width: width, height: sliceHeight });
    }

    currentY = nextCutY;
    await new Promise(r => requestAnimationFrame(r)); // Yield to prevent UI freeze
  }

  return chunks;
};

/**
 * Main function to process one or multiple images
 */
export const processImages = async (
  files: File[],
  targetHeight: number,
  mode: ProcessingMode,
  quality: number,
  onProgress: (progress: number) => void
): Promise<ProcessedSlice[]> => {

  // CASE 1: Stitch Mode (Combine all images horizontally)
  // Logic: Cut EVERY image into chunks first, then stitch ALL chunks side-by-side.
  if (mode === 'stitch') {
    let allChunks: Chunk[] = [];

    // Step 1: Generate chunks from all files
    for (let i = 0; i < files.length; i++) {
      // Progress 0-60%
      const progressBase = (i / files.length) * 60;
      onProgress(progressBase);

      const img = await loadImage(files[i]);
      const chunks = await generateChunks(img, targetHeight);
      allChunks.push(...chunks);

      URL.revokeObjectURL(img.src);
    }

    onProgress(70);

    // Step 2: Stitch all chunks horizontally
    if (allChunks.length === 0) return [];

    const totalWidth = allChunks.reduce((sum, chunk) => sum + chunk.width, 0);
    const maxHeight = Math.max(...allChunks.map(chunk => chunk.height));

    const stitchedCanvas = document.createElement('canvas');
    stitchedCanvas.width = totalWidth;
    stitchedCanvas.height = maxHeight;
    const ctx = stitchedCanvas.getContext('2d');

    if (!ctx) throw new Error("Canvas context failed");

    let currentX = 0;
    for (const chunk of allChunks) {
      ctx.drawImage(chunk.canvas, currentX, 0);
      currentX += chunk.width;
    }

    onProgress(90);

    const blob = await new Promise<Blob>((res, rej) => 
      stitchedCanvas.toBlob(b => b ? res(b) : rej(new Error('Blob failed')), 'image/jpeg', quality)
    );

    onProgress(100);

    return [{
      id: 'stitched-result',
      blob,
      url: URL.createObjectURL(blob),
      width: totalWidth,
      height: maxHeight,
      index: 1
    }];
  }

  // CASE 2: Slice Mode (Process each file independently and save as separate files)
  let allResults: ProcessedSlice[] = [];
  let currentIndex = 0;

  for (let i = 0; i < files.length; i++) {
    const progressStart = (i / files.length) * 100;
    const progressEnd = ((i + 1) / files.length) * 100;
    onProgress(progressStart);

    const img = await loadImage(files[i]);
    const chunks = await generateChunks(img, targetHeight);

    // Convert chunks to ProcessedSlice
    for (let j = 0; j < chunks.length; j++) {
       const chunk = chunks[j];
       // Progress interpolation
       onProgress(progressStart + ((j / chunks.length) * (progressEnd - progressStart)));

       const blob = await new Promise<Blob>((res, rej) => 
         chunk.canvas.toBlob(b => b ? res(b) : rej(new Error('Blob failed')), 'image/jpeg', quality)
       );

       allResults.push({
         id: `slice-${files[i].name}-${j}`,
         blob,
         url: URL.createObjectURL(blob),
         width: chunk.width,
         height: chunk.height,
         index: currentIndex + j + 1
       });
    }

    currentIndex += chunks.length;
    URL.revokeObjectURL(img.src);
  }

  onProgress(100);
  return allResults;
};

import React, { useState } from 'react';
import { Dropzone } from './components/Dropzone';
import { ResultPreview } from './components/ResultPreview';
import { processImages } from './utils/imageProcessor';
import { ProcessedSlice, ProcessingMode } from './types';
import { Scissors, Settings, Zap, Grid, Layers, Percent, Files } from 'lucide-react';
import { Button } from './components/Button';

const App: React.FC = () => {
  const [files, setFiles] = useState<File[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [slices, setSlices] = useState<ProcessedSlice[]>([]);

  // Settings
  const [targetHeight, setTargetHeight] = useState(10000);
  const [mode, setMode] = useState<ProcessingMode>('slice');
  const [quality, setQuality] = useState(90); // 1-100 range for UI

  const handleFilesSelect = async (selectedFiles: File[]) => {
    setFiles(selectedFiles);
    setIsProcessing(true);
    setProgress(0);
    setSlices([]);

    try {
      // Small delay to let UI render the loading state
      setTimeout(async () => {
        // Convert quality from 0-100 to 0.1-1.0
        const normalizedQuality = Math.max(0.1, Math.min(1.0, quality / 100));

        const result = await processImages(
          selectedFiles, 
          targetHeight, 
          mode, 
          normalizedQuality, 
          (p) => setProgress(p)
        );

        setSlices(result);
        setIsProcessing(false);
      }, 100);
    } catch (error) {
      console.error("Processing failed", error);
      alert("이미지 처리 중 오류가 발생했습니다.");
      setIsProcessing(false);
      setFiles([]);
    }
  };

  const handleReset = () => {
    setFiles([]);
    setSlices([]);
    setProgress(0);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-20">
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-600 p-2 rounded-lg text-white">
              <Scissors size={20} />
            </div>
            <h1 className="text-xl font-bold text-slate-900 tracking-tight">상세페이지 재단사</h1>
          </div>
          <div className="hidden sm:flex items-center gap-4 text-sm text-slate-500">
             <span className="flex items-center gap-1">
                 <Zap size={14} className="text-yellow-500" fill="currentColor"/>
                 스마트 분석 엔진 탑재
             </span>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-6xl w-full mx-auto px-4 py-12">
        {files.length === 0 ? (
          <div className="max-w-2xl mx-auto space-y-8 animate-fade-in-up">
            <div className="text-center space-y-4">
              <h2 className="text-3xl font-extrabold text-slate-900">
                긴 상세페이지, 한 번에 자르세요
              </h2>
              <p className="text-lg text-slate-600 max-w-lg mx-auto leading-relaxed">
                이미지 내용을 스마트하게 분석하여 최적의 위치에서 자르거나,<br/>
                여러 장의 이미지를 가로로 이어붙여 재구성하세요.
              </p>
            </div>

            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 space-y-8">
               <div className="flex items-center justify-between border-b border-slate-100 pb-4">
                   <div className="flex items-center gap-2 text-slate-700 font-medium">
                       <Settings size={18} />
                       <span>작업 설정</span>
                   </div>
               </div>

               {/* Mode Selection */}
               <div className="space-y-3">
                  <label className="block text-sm font-medium text-slate-700">작업 모드</label>
                  <div className="grid grid-cols-2 gap-4">
                    <button
                      onClick={() => setMode('slice')}
                      className={`relative flex flex-col items-center justify-center p-4 rounded-xl border-2 transition-all ${
                        mode === 'slice' 
                          ? 'border-indigo-600 bg-indigo-50 text-indigo-700' 
                          : 'border-slate-200 hover:border-indigo-200 text-slate-600'
                      }`}
                    >
                      <Layers className="mb-2" size={24} />
                      <span className="font-semibold">세로 분할 (기본)</span>
                      <span className="text-xs mt-1 opacity-75">긴 이미지를 여러 장으로 자르기</span>
                      {mode === 'slice' && <div className="absolute top-2 right-2 w-2 h-2 bg-indigo-600 rounded-full" />}
                    </button>

                    <button
                      onClick={() => setMode('stitch')}
                      className={`relative flex flex-col items-center justify-center p-4 rounded-xl border-2 transition-all ${
                        mode === 'stitch' 
                          ? 'border-indigo-600 bg-indigo-50 text-indigo-700' 
                          : 'border-slate-200 hover:border-indigo-200 text-slate-600'
                      }`}
                    >
                      <Grid className="mb-2" size={24} />
                      <span className="font-semibold">가로 이어붙이기</span>
                      <span className="text-xs mt-1 opacity-75">자른 후 가로로 합치기</span>
                      {mode === 'stitch' && <div className="absolute top-2 right-2 w-2 h-2 bg-indigo-600 rounded-full" />}
                    </button>
                  </div>
               </div>

               {/* Target Height Slider */}
               <div className="space-y-3">
                   <label className="block text-sm font-medium text-slate-700 flex justify-between">
                       <span>자르는 기준 높이</span>
                       <span className="text-indigo-600 font-mono font-bold">{targetHeight.toLocaleString()}px</span>
                   </label>
                   <input 
                        type="range" 
                        min="1000" 
                        max="20000" 
                        step="1000"
                        value={targetHeight}
                        onChange={(e) => setTargetHeight(Number(e.target.value))}
                        className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                   />
                   <p className="text-xs text-slate-400">
                       * {mode === 'slice' ? '이 높이를 기준으로 여러 장으로 나뉩니다.' : '이미지를 이 높이로 자른 뒤 가로로 배치합니다.'} (스마트 여백 감지)
                   </p>
               </div>

               {/* Quality Slider */}
               <div className="space-y-3">
                   <label className="block text-sm font-medium text-slate-700 flex justify-between">
                       <span>이미지 품질 (용량 압축)</span>
                       <span className={`font-mono font-bold ${quality < 80 ? 'text-orange-500' : 'text-indigo-600'}`}>
                         {quality}%
                       </span>
                   </label>
                   <div className="flex items-center gap-4">
                     <Percent size={16} className="text-slate-400" />
                     <input 
                          type="range" 
                          min="10" 
                          max="100" 
                          step="5"
                          value={quality}
                          onChange={(e) => setQuality(Number(e.target.value))}
                          className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                     />
                   </div>
                   <p className="text-xs text-slate-400">
                       * 낮을수록 용량이 줄어들지만 화질이 저하될 수 있습니다. (추천: 80-90%)
                   </p>
               </div>
            </div>

            <Dropzone onFilesSelect={handleFilesSelect} />

          </div>
        ) : isProcessing ? (
          <div className="max-w-xl mx-auto text-center space-y-8 py-20 animate-pulse">
             <div className="relative w-24 h-24 mx-auto">
                 <div className="absolute inset-0 border-4 border-slate-200 rounded-full"></div>
                 <div 
                    className="absolute inset-0 border-4 border-indigo-600 rounded-full border-t-transparent animate-spin"
                 ></div>
             </div>
             <div className="space-y-2">
                 <h3 className="text-xl font-bold text-slate-900">
                    {mode === 'slice' ? '이미지를 분석하고 자르는 중...' : '이미지를 자르고 이어붙이는 중...'}
                 </h3>
                 <p className="text-slate-500">
                     {files.length}장의 이미지를 처리하고 있습니다.
                 </p>
             </div>
             <div className="w-full bg-slate-200 rounded-full h-2.5 dark:bg-slate-700">
                <div className="bg-indigo-600 h-2.5 rounded-full transition-all duration-300" style={{ width: `${progress}%` }}></div>
             </div>
             <p className="font-mono text-slate-400">{progress}% 완료</p>
          </div>
        ) : (
          <ResultPreview 
            slices={slices} 
            onReset={handleReset} 
            originalFileName={files[0]?.name || 'result.jpg'}
          />
        )}
      </main>

      <footer className="bg-white border-t border-slate-200 py-8 mt-12">
          <div className="max-w-6xl mx-auto px-4 text-center text-slate-400 text-sm">
              &copy; {new Date().getFullYear()} 상세페이지 재단사. Local processing ensures privacy.
          </div>
      </footer>
    </div>
  );
};

export default App;
